function searchScore(i,q){q=q.trim().toLowerCase();if(!q)return 1;const title=String(i.title||'').toLowerCase(),description=String(i.description||'').toLowerCase(),group=String(i.group||'').toLowerCase(),key=String(i.key||'').toLowerCase(),url=String(i.url||'').toLowerCase(),body=String(i.body||'').toLowerCase();const tokens=q.split(/\s+/).filter(Boolean);let score=0;if(title===q)score=120;else if(title.startsWith(q))score=95;else if(title.includes(q))score=80;else if(tokens.every(t=>title.includes(t)))score=70;if(description.includes(q))score=Math.max(score,45);if(group.includes(q)||key===q)score=Math.max(score,40);if(url.includes(q))score=Math.max(score,28);if(body.includes(q))score=Math.max(score,14);else if(tokens.length>1&&tokens.every(t=>body.includes(t)))score=Math.max(score,10);return score}
